      appendMedicine(){if(!this.medicinePending&&this.medicineIndex<0)return true;if(!this.medicine.name.trim()){this.error='Nhập tên thuốc trước khi ghi liều.';this.$refs.medicineName?.focus();return false}const m=this.medicine,line=[m.name.trim(),[m.dose.trim(),m.unit.trim()].filter(Boolean).join(' '),m.route.trim()].filter(Boolean).join(' · '),lines=String(this.draft.medication||'').split('\n');let text;if(this.medicineIndex>=0){lines[this.medicineIndex]=line;text=lines.join('\n')}else text=[this.draft.medication,line].filter(v=>v?.trim()).join('\n');if(text.length>240){this.error='Nội dung thuốc tối đa 240 ký tự. Rút gọn ghi chú trước khi thêm.';return false}this.draft.medication=text;this.resetMedicine();return true},
